insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Local SEO Services","heading":"Get Found Where Your Customers Are Looking","body":"Local SEO is the work of appearing when somebody nearby searches for what you do. It runs across your Google Business Profile, your listings, your reviews and your service pages, and it is measured across your whole service area rather than as one number.","primaryCta":{"label":"View Local SEO Packages","href":"/monthly-seo-packages#local"},"showcase":[{"kind":"share","label":"A month of Citywide","title":"Where the Work Goes","unit":"tasks in a Citywide month, at the published maximums","series":[{"label":"Review replies","value":20},{"label":"Citations","value":15},{"label":"Profile posts","value":12},{"label":"Review requests","value":4}]},{"kind":"channels","label":"Three tiers","title":"Sized by Area","items":["Neighborhood","Citywide","Metro"]}]}'::jsonb, 0 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'audience-fit', 'cardGrid', 'surface', '{"variant":"cards","columns":4,"eyebrow":"Is This You","heading":"Who Local SEO Is For","body":"The first three sort by how customers reach you. The fourth is about scale, so a practice with four offices is both the third and the fourth.","cards":[{"title":"Storefront","icon":"storefront","body":"Customers come to you, and being findable on a map is most of the battle. Shops, showrooms, studios, gyms."},{"title":"Service Area","icon":"map-pin","body":"You travel to the customer, so you are ranked against an area rather than an address. Trades, contractors, mobile services."},{"title":"Appointment-Based","icon":"calendar","body":"Customers book time with you, and they compare two or three options before doing it. Practices, clinics, salons, consultants."},{"title":"Multi-Location","icon":"building","body":"Several locations competing across the same broad area. Each one needs its own profile, its own citations and its own tracking, or they compete with each other."}]}'::jsonb, 1 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'includes', 'cardGrid', 'white', '{"variant":"cards","columns":3,"eyebrow":"What You Get","heading":"What Local SEO Includes","body":"Every package includes all six. Tiers differ by volume, not by what is included.","cards":[{"title":"SEO Strategy & Roadmap","icon":"compass","body":"A plan for the next quarter rather than a list of tasks, with the reasoning behind the order it runs in."},{"title":"Content & On-Page Optimization","icon":"pencil","body":"Service pages, titles, descriptions and on-page structure written for how people in your area actually search."},{"title":"Technical Monitoring","icon":"gauge","body":"Crawling, indexing and site health watched month to month, so a problem is found before it costs you visibility."},{"title":"Detailed Monthly Reporting","icon":"bar-chart","body":"What was tracked, what moved and what did not, in language that does not need translating."},{"title":"Monthly Project Recap","icon":"message-square","body":"A person walking through the month rather than a file dropped into an inbox, with room to ask questions."},{"title":"Review Management","icon":"star","body":"Review requests sent to real customers and replies written to what comes back, positive and negative alike."}]}'::jsonb, 2 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'packages', 'pricingCards', 'surface', '{"eyebrow":"Pricing","heading":"Local SEO Packages","body":"Three tiers, sized by how much ground you are competing for. Every tier includes all six of the deliverables above.","packageIds":["local-neighborhood","local-citywide","local-metro"]}'::jsonb, 3 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'custom-scope', 'fullWidthText', 'surface', '{"heading":"Working With Something Bigger?","body":"If the scope is bigger or more involved than what is here, JMC will look at it and put together a quote. However many locations are involved, a business competing in local results is still a Local engagement.","cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 4 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'sprint-callout', 'calloutBanner', 'white', '{"heading":"Or Start With a Launch Sprint","body":"The Neighborhood Launch Sprint is $799, one-time, completed within 30 days. It builds the local foundation and finishes with a 30-day roadmap. Begin monthly service within 30 days of the sprint finishing and the onboarding fee on any Local package is waived, up to $649.","primaryCta":{"label":"View Launch Sprints","href":"/launch-sprints"},"secondaryCta":{"label":"View Local SEO Packages","href":"/monthly-seo-packages#local"}}'::jsonb, 5 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'visibility-system', 'cardGrid', 'white', '{"variant":"cards","columns":5,"eyebrow":"The System","heading":"The Local Visibility System","body":"Five parts, worked together. Any one of them on its own tends to stall.","cards":[{"title":"Google Business Profile","icon":"storefront","body":"Categories, services, information, photos and posts. For many local searches the profile is what is being ranked.","href":"/google-business-profile-optimization"},{"title":"Citations & NAP Consistency","icon":"shield-check","body":"One standard for your name, address and phone number, applied across the listings that currently disagree with each other."},{"title":"Reviews","icon":"star","body":"Requests to real customers and replies to what arrives. Nothing fabricated, nothing incentivised."},{"title":"Local Search Grid Tracking","icon":"map-pin","body":"Visibility measured across a grid of points in your service area rather than as one blended rank, so you can see where you are strong and where you are not."},{"title":"Strategic SEO Pages","icon":"file-text","body":"Pages built for the services and areas worth competing for, rather than one page trying to hold all of them."}]}'::jsonb, 6 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Local SEO Questions","items":[{"question":"How long before there are results?","answer":"Local tends to move faster than national search because the competing field is smaller, and profile or listing corrections can show within weeks. Ranking movement across a service area is a longer arc, usually a few months before the shape of it is clear. Nobody can honestly give you a date, and the recap tells you which stage the work is at each month."},{"question":"Is there a contract?","answer":"Yes. Twelve months, then month to month, with 30 days written notice to end it. The term exists because the work compounds and a three-month engagement cannot show what a twelve-month one can."},{"question":"What does the onboarding fee cover?","answer":"The audit, tracking setup, the foundational on-page work and the local visibility setup: profile, categories, services, citations and the grid baseline. It is the work that has to happen once before the monthly work means anything."},{"question":"How is this different from Traditional SEO?","answer":"Local SEO is for businesses competing for customers in a defined area, however many locations they run in it. Traditional SEO is for businesses competing across multiple markets, multiple service lines, or genuinely competitive search. It is a difference in reach, not in size."},{"question":"Do you guarantee rankings?","answer":"No, and anyone who does is guessing. What is guaranteed is the scope, the reporting, and knowing exactly what was done and why."},{"question":"What is local search grid tracking?","answer":"Instead of checking your rank from one point, it checks from a grid of points across your service area. That matters because local results change street by street: you can be first near your own address and invisible four miles away, and one blended number hides that completely."},{"question":"What if the business is not in Houston?","answer":"Local SEO is not limited to the Houston area. JMC is based in League City and most clients are nearby, but the work is the same for a business competing in a defined area anywhere."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 7 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Not Sure a Package Fits?","body":"Start with a visibility review instead. Where you appear across your service area today, what is holding it back, and which of those gaps is worth closing first — before anything is bought.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 8 from public.pages where slug = '/local-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Traditional SEO Services","heading":"Built for Businesses Competing Beyond One Market","body":"When buyers are spread across cities, regions or the whole country, the work changes shape. Traditional SEO is strategy, strategic pages, technical monitoring and authority, measured against a competitive field rather than a service area.","primaryCta":{"label":"View Traditional SEO Packages","href":"/monthly-seo-packages#traditional"},"showcase":[{"kind":"scale","label":"What scales","title":"Tracked Keywords by Tier","unit":"keywords tracked each month, up to","series":[{"label":"Regional","value":60},{"label":"National","value":75},{"label":"National+","value":90}]},{"kind":"channels","label":"Also by tier","title":"Sized by Reach","items":["Tracked competitors","Strategic pages","Market coverage"]}]}'::jsonb, 0 from public.pages where slug = '/traditional-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'audience-fit', 'cardGrid', 'surface', '{"variant":"cards","columns":4,"eyebrow":"Is This You","heading":"Who Traditional SEO Is For","body":"The first four describe reach rather than size: one address selling nationally belongs here, seven addresses inside one metro does not. The four below them are the sectors that usually have that reach.","groupLabels":[{"at":0,"label":"Who it is for"},{"at":4,"label":"Industries that usually land here"}],"cards":[{"title":"Multiple Markets","icon":"globe","body":"The business sells into more than one city, region or state, and the same search returns a different set of competitors in each of them."},{"title":"Multiple Service Lines","icon":"layers","body":"Several distinct offerings, each with its own buyers and its own search language. One page trying to hold all of them ranks for none of them."},{"title":"Competitive Search","icon":"target","body":"High-value searches with established competitors already sitting on them, where progress starts on the specific terms rather than the broadest one."},{"title":"Longer Buying Cycles","icon":"clipboard-check","body":"Procurement, requests for quotes and research-heavy purchases rather than a phone call. Several people search for different things before one decision is made."},{"title":"Energy & Petrochemical","icon":"lightning","body":"Suppliers and service firms found by specification, standard and part number rather than by name.","href":"/industries/energy-petrochemical"},{"title":"Maritime & Logistics","icon":"ship","body":"Port, freight and marine businesses searched by route, mode and capability.","href":"/industries/maritime-logistics"},{"title":"Commercial Construction","icon":"hard-hat","body":"Contractors, civil firms and suppliers qualified on project type long before any bid conversation.","href":"/industries/commercial-construction-infrastructure"},{"title":"Aerospace & Aviation","icon":"plane","body":"Manufacturers and service providers where certification is the first filter a buyer applies.","href":"/industries/aerospace-aviation"}],"cta":{"label":"Explore Industries","href":"/industries"}}'::jsonb, 1 from public.pages where slug = '/traditional-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'includes', 'cardGrid', 'white', '{"variant":"cards","columns":5,"eyebrow":"What You Get","heading":"What Traditional SEO Includes","body":"Every package includes all five. Tiers differ by scale, not by what is included.","cards":[{"title":"SEO Strategy & Roadmap","icon":"compass","body":"A plan for the quarter with the reasoning behind the order, rather than a list of tasks arriving one at a time."},{"title":"Strategic SEO Pages","icon":"file-text","body":"Pages built for specific searches worth competing for, produced to a schedule rather than when there is time."},{"title":"Technical Monitoring","icon":"gauge","body":"Crawling, indexing and site health watched month to month, with issues flagged as they appear rather than found in an annual audit."},{"title":"Reporting & Monthly Recap","icon":"bar-chart","body":"Dashboard reporting alongside a recap delivered by Loom or a video call, so somebody explains it rather than sending it."},{"title":"Authority-Building Recommendations","icon":"network","body":"What would strengthen the site''s authority and why, as advice you can act on. Recommendations, not placements bought on your behalf."}]}'::jsonb, 2 from public.pages where slug = '/traditional-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'packages', 'pricingCards', 'surface', '{"eyebrow":"Pricing","heading":"Traditional SEO Packages","body":"Three tiers, sized by footprint. Every tier includes all five deliverables above.","packageIds":["traditional-regional","traditional-national","traditional-national-plus"]}'::jsonb, 3 from public.pages where slug = '/traditional-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'custom-scope', 'fullWidthText', 'surface', '{"heading":"Working With Something Bigger?","body":"Some engagements do not fit a tier. Several brands under one owner, a dozen service lines, a migration running alongside the SEO work, or a footprint wider than National+ covers.\n\nThose get scoped rather than priced from a card. JMC looks at the sites, the markets and the competitive field, and comes back with what the work would involve, what it would cost, and what the first quarter would be spent on. The same monthly recap applies whatever the size.","cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 4 from public.pages where slug = '/traditional-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'sprint-callout', 'waiverMatrix', 'white', '{"eyebrow":"Another Way In","heading":"Or Start With a Launch Sprint","body":"A Launch Sprint is a fixed-scope piece of work bought once rather than monthly: the audit, the technical foundation and the first set of pages, done in one pass so a campaign does not spend its first two months on groundwork.\n\nEach sprint is one-time, completed within 30 days, and finishes with a 30-day roadmap. Begin monthly service within 30 days of the sprint completing and the onboarding fee on the matching package is waived.","sprintHeading":"Sprint","priceHeading":"One-time","waivesHeading":"Waives onboarding on","rows":[{"sprint":"Regional Launch Sprint","price":"$1,495","waives":"Regional"},{"sprint":"National Launch Sprint","price":"$2,295","waives":"National or National+"}],"condition":"Monthly service must begin within 30 calendar days of sprint completion.","cta":{"label":"View Launch Sprints","href":"/launch-sprints"}}'::jsonb, 5 from public.pages where slug = '/traditional-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'content-technical', 'cardGrid', 'surface', '{"variant":"split","columns":3,"eyebrow":"In Detail","heading":"Content and Technical Work, Explained","body":"Three items from the list above that get misread more often than the rest.","cards":[{"title":"Strategic SEO Pages","icon":"file-text","body":"Pages built for a specific search that a buyer actually makes, with the depth to answer it. They are not blog posts: a blog post is published and left, a strategic page is built to rank for something and maintained until it does."},{"title":"Technical Monitoring","icon":"gauge","body":"Ongoing issue flagging rather than a one-time audit. Sites break quietly, and a redirect chain or a noindex tag introduced during a redesign can undo months of work before anyone notices."},{"title":"Authority-Building Recommendations","icon":"network","body":"JMC advises on authority building and does not sell link placements. What you get is what would genuinely strengthen the site''s standing and why, including the parts you are best placed to do yourself. Bought links are a risk taken with your domain, not with the agency''s."}]}'::jsonb, 6 from public.pages where slug = '/traditional-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'footprint', 'featureSplit', 'white', '{"align":"left","eyebrow":"Coverage","heading":"Coverage That Scales With the Business","body":"The three tiers are not different services. They are the same work applied to a wider footprint: more keywords tracked, more competitors watched, and more strategic pages produced each month.\n\nWhich one fits comes out of the visibility review rather than out of a headcount. A business competing in two states against four serious competitors is a different problem from one competing nationally against ten, and the coverage is what has to match.","tableHeadings":["","Regional","National","National+"],"tableRows":[{"cells":["Tracked keywords","Up to 60","Up to 75","Up to 90"]},{"cells":["Tracked competitors","Up to 5","Up to 8","Up to 10"]},{"cells":["Strategic pages a month","Up to 2","Up to 3","Up to 4"]}],"groups":[]}'::jsonb, 7 from public.pages where slug = '/traditional-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Traditional SEO Questions","items":[{"question":"How long before there are results?","answer":"Longer than local, because the competing field is bigger and the buying cycles behind it are slower. Technical fixes can show within weeks, but movement on competitive terms is usually a matter of months, and it starts on the specific searches before the broad ones. The recap says which stage the work is at rather than implying steady progress."},{"question":"Is there a contract?","answer":"Yes. Twelve months, then month to month, with 30 days written notice to end it. The term exists because this work compounds and a short engagement cannot show what a full one can."},{"question":"What does the onboarding fee cover?","answer":"The technical and on-page audit, tracking setup across markets, competitor analysis, and the foundational fixes that have to happen once before the monthly work means anything."},{"question":"Do you build links?","answer":"No. JMC advises on authority building and does not sell or place links. Bought placements are a risk taken with your domain rather than with the agency''s, and the recommendations you get are the ones JMC would follow on its own domain."},{"question":"How is this different from Local SEO?","answer":"Local SEO is for businesses competing for customers in a defined area, however many locations they run in it. Traditional SEO is for businesses competing across markets, service lines or genuinely competitive search. It is a difference in reach, not in size, and a large single-area business is still a Local engagement."},{"question":"Do you guarantee rankings?","answer":"No, and anyone who does is guessing. What is guaranteed is the scope, the reporting, and knowing exactly what was done and why."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 8 from public.pages where slug = '/traditional-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Start With a Visibility Review","body":"Where the business appears across its markets today, who is holding the space, and which gap is worth closing first.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 9 from public.pages where slug = '/traditional-seo-services';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroCentered', NULL, '{"eyebrow":"Monthly SEO Packages","heading":"The Prices Are on This Page","body":"Six monthly packages across two service lines, with what each one includes and what it costs. Nothing here is behind a call, because a price you have to ask for is a price that changes depending on who is asking.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 0 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'path', 'cardGrid', 'surface', '{"variant":"cards","columns":2,"eyebrow":"Start Here","heading":"Two Paths, Sorted by Reach","body":"Which one fits comes down to where a business competes, not how large it is.","cards":[{"title":"Local SEO","icon":"map-pin","meta":"From $875 a month","body":"For businesses competing for customers in a defined area, however many locations they run inside it.","cta":{"label":"View Local SEO Packages","href":"#local"}},{"title":"Traditional SEO","icon":"globe","meta":"From $2,295 a month","body":"For businesses competing across multiple markets, multiple service lines, or genuinely competitive search.","cta":{"label":"View Traditional SEO Packages","href":"#traditional"}}]}'::jsonb, 1 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'local', 'pricingCards', 'white', '{"eyebrow":"Local SEO","heading":"Local SEO Packages","body":"Three tiers, sized by how much ground you are competing for.","packageIds":["local-neighborhood","local-citywide","local-metro"]}'::jsonb, 2 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'local-included', 'cardGrid', 'white', '{"variant":"compact","columns":3,"eyebrow":"Every Local Tier","heading":"Included in Every Local Package","body":"The three tiers differ by volume, not by what is included.","cards":[{"title":"SEO Strategy & Roadmap","icon":"compass","body":"A plan for the quarter, with the reasoning behind the order."},{"title":"Content & On-Page Optimization","icon":"pencil","body":"Service pages, titles, descriptions and page structure."},{"title":"Technical Monitoring","icon":"gauge","body":"Crawling, indexing and site health watched month to month."},{"title":"Detailed Monthly Reporting","icon":"bar-chart","body":"What was tracked, what moved, and what did not."},{"title":"Monthly Project Recap","icon":"message-square","body":"Delivered by Loom or a video call, with room to ask questions."},{"title":"Review Management","icon":"star","body":"Requests sent to real customers, and replies to what arrives."}]}'::jsonb, 3 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'local-custom', 'fullWidthText', 'white', '{"treatment":"note","heading":"Bigger Than Metro?","body":"If the scope is bigger or more involved than what is here, JMC will look at it and put together a quote. That is still a Local engagement, however many locations are involved.","cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 4 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'local-onboarding', 'featureSplit', 'white', '{"align":"left","eyebrow":"The One-Time Fee","heading":"What Local Onboarding Covers","body":"Every Local tier carries a one-time onboarding fee, from $349 to $649. It pays for the work that has to happen once before the monthly work means anything: nothing built on an unaudited foundation is worth reporting on.","groups":[{"title":"Kickoff and access setup","body":"Accounts, permissions and the handover needed before anything can be audited."},{"title":"Local SEO audit","body":"The current foundation reviewed end to end, with findings ranked by impact."},{"title":"Local keyword and competitor snapshot","body":"What the business should be found for, and who is currently being found instead."},{"title":"Search Console and Bing setup","body":"Set up or verified, so the reporting has something real behind it from month one."},{"title":"Google Business Profile audit and core optimization","body":"Categories, services, hours and the fields that decide whether the profile shows at all."},{"title":"Citation audit and NAP standard","body":"One agreed name, address and phone format, and a list of where it is currently wrong."},{"title":"Schema, sitemap and robots.txt review","body":"The technical files that decide what search engines can read."},{"title":"Titles and meta descriptions","body":"Written for the priority pages rather than generated across the whole site."},{"title":"Local search grid baseline","body":"Where the business ranks across the service area today, so later months have something to compare against."}],"cta":{"label":"Get Started","href":"/contact"}}'::jsonb, 5 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'traditional', 'pricingCards', 'surface', '{"eyebrow":"Traditional SEO","heading":"Traditional SEO Packages","body":"Three tiers, sized by footprint rather than by headcount.","packageIds":["traditional-regional","traditional-national","traditional-national-plus"]}'::jsonb, 6 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'traditional-included', 'cardGrid', 'surface', '{"variant":"compact","columns":3,"eyebrow":"Every Traditional Tier","heading":"Included in Every Traditional Package","body":"The three tiers differ by footprint, not by what is included.","cards":[{"title":"SEO Strategy & Roadmap","icon":"compass","body":"The same plan, applied across markets rather than an area."},{"title":"Strategic SEO Pages","icon":"file-text","body":"Pages built for specific searches, produced to a schedule."},{"title":"Technical Monitoring","icon":"gauge","body":"Issues flagged as they appear, not found in an annual audit."},{"title":"Reporting & Monthly Recap","icon":"bar-chart","body":"Dashboard reporting alongside the recap, in both cases explained."},{"title":"Authority-Building Recommendations","icon":"network","body":"Advice on what would strengthen authority. Recommendations, not link placements."}]}'::jsonb, 7 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'traditional-custom', 'fullWidthText', 'surface', '{"treatment":"note","heading":"Bigger Than National+?","body":"If the footprint is wider or the search landscape more competitive than what is published here, JMC will look at the scope and put together a quote rather than forcing it into a tier that does not fit.","cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 8 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'traditional-onboarding', 'featureSplit', 'surface', '{"align":"left","eyebrow":"The One-Time Fee","heading":"What Traditional Onboarding Covers","body":"Every Traditional tier carries a one-time onboarding fee, from $895 to $1,295. The scope is genuinely different from Local rather than the same setup at a higher price: the audit covers a whole site across several markets, not a profile in one area.","groups":[{"title":"Kickoff and access setup","body":"Accounts, permissions and the handover needed before anything can be audited."},{"title":"Technical and on-page SEO audit","body":"A full review across the site rather than a local profile, since the competition is not in one area."},{"title":"Keyword and competitor analysis","body":"Across every market and service line in scope, not a single radius."},{"title":"Search Console and Bing setup","body":"Set up or verified, so the reporting has something real behind it from month one."},{"title":"Schema, sitemap and robots.txt review","body":"The technical files that decide what search engines can read."},{"title":"Titles and meta descriptions","body":"Written for the priority pages rather than generated across the whole site."},{"title":"Backlink audit","body":"What authority already exists and what is actively working against it."}],"cta":{"label":"Get Started","href":"/contact"}}'::jsonb, 9 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'sprint-waiver', 'waiverMatrix', 'surface', '{"eyebrow":"Another Way In","heading":"Start With a Launch Sprint","body":"A sprint is the onboarding work done standalone, with a roadmap attached. That is why the waiver exists rather than being a discount: it is close to the same job, bought once, with no monthly commitment behind it.","sprintHeading":"Sprint","priceHeading":"One-time","waivesHeading":"Waives onboarding on","rows":[{"sprint":"Neighborhood Launch Sprint","price":"$799","waives":"Neighborhood, Citywide, or Metro"},{"sprint":"Regional Launch Sprint","price":"$1,495","waives":"Regional"},{"sprint":"National Launch Sprint","price":"$2,295","waives":"National or National+"}],"condition":"Monthly service must begin within 30 calendar days of sprint completion.","cta":{"label":"View Launch Sprints","href":"/launch-sprints"}}'::jsonb, 10 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'monthly-recap', 'reportingBlock', 'white', '{"eyebrow":"Reporting","heading":"The Monthly Recap","body":"Included in every package in both lanes, at every tier.","did":"The specific work completed that month, named task by task.","why":"Why that work was the priority ahead of everything else in the queue.","changed":"What moved, reported honestly, including the months where little did.","next":"Next month''s priorities, so nothing in the following recap is a surprise.","cta":{"label":"See How JMC Reports SEO Progress","href":"/seo-reporting"}}'::jsonb, 11 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'surface', '{"eyebrow":"Questions","heading":"Pricing Questions","items":[{"question":"Why a 12-month term?","answer":"Because SEO compounds and a short engagement cannot show what a full one can. Most of the foundational work lands in the first quarter and most of the return on it arrives later, so a three-month contract would mean paying for the setup and leaving before the benefit. The term applies to all six monthly tiers in both lanes."},{"question":"What happens after 12 months?","answer":"It runs month to month from then on, for as long as you want it to, and either side can end it with 30 days written notice. There is no second term and no automatic re-commitment."},{"question":"What does the onboarding fee cover?","answer":"On Local: the audit, tracking setup, foundational optimization and the local visibility setup, meaning profile, categories, services, citations and the grid baseline. On Traditional: the audit, tracking setup, foundational optimization and roadmap development. A Launch Sprint can waive it entirely if monthly service begins within 30 days of the sprint finishing."},{"question":"Can tiers be changed later?","answer":"Upgrades happen any time. The deliverables adjust from the next cycle and there is no additional onboarding fee. Downgrades take effect at renewal rather than mid-term."},{"question":"Which lane fits?","answer":"Reach decides it, not size. A business competing for customers in a defined area is Local, however many locations it runs there. A business competing across markets, service lines or competitive search is Traditional. Both service pages set out the difference in more detail."},{"question":"Does this include blog content?","answer":"Yes. Strategic SEO Pages covers all written SEO content, blog posts included. Early phases usually prioritise local and industry pages first, simply because blog content needs somewhere to point before it does much good."},{"question":"What is not included?","answer":"Paid advertising, web design and development, social media posting, and link building. Authority building is covered as recommendations rather than as placements bought on your behalf."},{"question":"Is there anything without a term?","answer":"Launch Sprints. One-time, completed within 30 days, no term and no renewal, ending with a roadmap that is yours whatever you decide next."},{"question":"Can Local and Traditional be combined?","answer":"Yes, as a custom plan. It is usually scoped from the Local deliverable side with the Traditional work layered on, and it needs a conversation rather than a package number."},{"question":"What if none of these fit?","answer":"Larger or more involved scopes get a custom quote. That is a real answer rather than a polite one: several kinds of engagement genuinely do not fit into three tiers."}],"cta":{"label":"Request a Visibility Review","href":"/contact"}}'::jsonb, 12 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'final-cta', 'finalCta', NULL, '{"heading":"Not Sure Which One Fits?","body":"A visibility review covers where you appear now, what is holding it back, and which package or sprint actually matches the problem.","primaryCta":{"label":"Request a Visibility Review","href":"/contact"},"secondaryCta":{"label":"View Launch Sprints","href":"/launch-sprints"}}'::jsonb, 13 from public.pages where slug = '/monthly-seo-packages';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'hero', 'heroSplit', NULL, '{"eyebrow":"Google Business Profile Optimization","heading":"Your Google Business Profile Is Doing More Work Than Your Website","body":"For most local searches the profile is what people see, read and act on, often without ever opening a website. Getting it right is the fastest visibility work available to a local business.","primaryCta":{"label":"Get a Free Google Business Profile Audit","href":"#free-audit"},"showcase":[{"kind":"profile","label":"What gets worked","title":"The Profile Itself","items":["Categories and services","Business information","Photos and posts","Reviews and replies"]},{"kind":"channels","label":"Where it shows","title":"Local Surfaces","items":["Map results","Local search","Profile panel"]}]}'::jsonb, 0 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'what-it-affects', 'cardGrid', 'surface', '{"variant":"cards","columns":3,"eyebrow":"Why It Matters","heading":"What the Profile Actually Affects","body":"Three things, none of which the website controls.","cards":[{"title":"Map Results","icon":"map-pin","body":"Where the business appears when somebody searches nearby. The profile is what is being ranked in that result, not the website behind it."},{"title":"First Impressions","icon":"storefront","body":"Hours, photos, services and reviews are read directly in the results. For a lot of searches that is the whole of what someone sees before deciding."},{"title":"Direct Actions","icon":"phone","body":"Calls, direction requests and website clicks all happen from the profile itself. A weak one loses those before a visit ever starts."}]}'::jsonb, 1 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'problems', 'cardGrid', 'white', '{"variant":"compact","columns":3,"eyebrow":"Sound Familiar","heading":"Common Profile Problems","body":"Most profiles have at least two of these. Several of them take minutes to fix and have been costing visibility for years.","cards":[{"title":"Incomplete Categories","icon":"list-checks","body":"Your primary category is wrong, or the secondary ones were never set. Categories decide which searches you are eligible for at all."},{"title":"Inconsistent Information","icon":"warning","body":"Your name, address or phone number disagrees with what other listings say. Search engines notice the disagreement even when customers do not."},{"title":"No Recent Activity","icon":"calendar","body":"Your profile has not been posted to in months. An inactive profile reads as an inactive business."},{"title":"Unanswered Reviews","icon":"message-square","body":"Reviews sitting without a reply, good ones as well as bad. The reply is read by everyone who arrives afterwards."},{"title":"Missing Services","icon":"file-text","body":"Your services and products are undefined, so the profile cannot match a search for something you genuinely do."},{"title":"No Visibility Tracking","icon":"search","body":"You have no way of knowing whether any of it is working, or where in your area you are visible and where you are not."}]}'::jsonb, 2 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'what-jmc-does', 'cardGrid', 'surface', '{"variant":"cards","columns":3,"eyebrow":"The Work","heading":"What JMC Does to a Profile","body":"Three things once, and three things every month, on a profile you own throughout.","groupLabels":[{"at":0,"label":"One-time foundation"},{"at":3,"label":"Ongoing every month"}],"cards":[{"title":"Profile Audit","icon":"clipboard-check","body":"A full review of the profile as it stands, against how people in your area actually search for what you do."},{"title":"Category & Services Setup","icon":"list-checks","body":"Primary and secondary categories set deliberately, with services and products defined so the profile can match real searches."},{"title":"NAP & Citation Consistency","icon":"shield-check","body":"Name, address and phone standardised, then corrected across the listings that carry an older version of them."},{"title":"Ongoing Profile Posts","icon":"pencil","body":"Regular posts through the month, so the profile stays active rather than going quiet after the setup work finishes."},{"title":"Review Requests & Replies","icon":"star","body":"Requests sent to real customers and replies written to what arrives, positive and negative alike. Nothing is fabricated or incentivised."},{"title":"Local Search Grid Tracking","icon":"map-pin","body":"Visibility measured across the service area rather than as one blended number, so you can see where the profile is strong and where it is not.","visual":"searchGrid"}]}'::jsonb, 3 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'faq', 'faq', 'white', '{"eyebrow":"Questions","heading":"Profile Questions","items":[{"question":"Is this the same as Google My Business?","answer":"Yes. Google renamed Google My Business to Google Business Profile, and a lot of people still search for the old name. It is the same listing and the same work."},{"question":"Can this be done without a monthly package?","answer":"Yes. The Neighborhood Launch Sprint covers the foundation work as a one-time engagement and finishes with a 30-day roadmap, with no obligation to continue into a monthly package afterwards."},{"question":"How long before the profile improves?","answer":"Some changes show up almost immediately: corrected categories, services, hours and information can be reflected within days. Movement in map rankings is slower and depends on how competitive your area is, which is why the reporting separates the two rather than blending them."},{"question":"Who owns the profile?","answer":"You do, always. JMC requests manager access to a profile you own and never takes ownership of one. If the engagement ends, access is removed and nothing has to be handed back, because it was never held."},{"question":"Can suspended or duplicate profiles be fixed?","answer":"Duplicates can usually be merged or removed. Suspensions vary: some are caused by fixable information problems and some are not, and nobody can promise reinstatement. What JMC will do is look at the cause honestly and tell you whether it is worth pursuing."},{"question":"Does this help a business with no storefront?","answer":"Yes. A service-area business hides its address and is ranked against the area it covers, which makes categories, service definitions and listing consistency do more of the work. JMC is a service-area business itself and does not publish a street address."}],"cta":{"label":"Get a Free Google Business Profile Audit","href":"#free-audit"}}'::jsonb, 4 from public.pages where slug = '/google-business-profile-optimization';
insert into public.sections (page_id, key, type, tone, data, position) select id, 'free-audit', 'auditForm', NULL, '{"eyebrow":"Free Profile Audit","heading":"Get a Free Google Business Profile Audit","body":"A written audit of the profile, and of the site behind it, built on the same four headings as the monthly recap: what is there, why it matters, what is working and what is not, and what to do next.","covers":["Categories, services and business information","Listing consistency across the web","Profile activity, photos and reviews","Where the profile is visible across the service area"],"note":"No call required.","submitLabel":"Get a Free Google Business Profile Audit","profileHelp":"Optional. Paste the map listing link if you have it handy.","source":"Free Profile Audit"}'::jsonb, 5 from public.pages where slug = '/google-business-profile-optimization';
